export { createSequenceDiff, sequenceDiff }
export type { SequenceAlgorithm, SequenceDiff }

// oxlint-disable unicorn/consistent-function-scoping -- a Web Worker runs the factory below from its source, so every helper lives inside it
import { sequenceDiff, type SequenceDiff } from "@/lib/diff-sequence"
import type { DiffHunk, DiffLine, DiffOptions, FileDiff, IgnoreWhitespace, TextDiff } from "@/lib/diff-types"

type LineDiff = {
  /** Splits text into lines the way the diff does: `\n` or `\r\n`, no empty last line after a final newline. */
  splitLines: (text: string) => string[]
  diffText: (oldText: string, newText: string, options?: DiffOptions) => TextDiff
  /** The unified-diff heading git would give a hunk starting at `oldStart`: the nearest line above it that starts a definition. */
  headingAbove: (lines: readonly string[], oldStart: number) => string | undefined
}

/**
 * Line diffs and hunks over a sequence diff. Self-contained like `createSequenceDiff`, which it takes as its only
 * input, so a Web Worker can run both from their source.
 */
function createLineDiff(sequence: SequenceDiff): LineDiff {
  const BINARY_SNIFF = 8000
  const CONTEXT = 0
  const REMOVED = 1
  const ADDED = 2

  function indentOf(line: string | undefined) {
    if (line === undefined) return 0
    let width = 0
    for (const char of line) {
      if (char === " ") width++
      else if (char === "\t") width += 4
      else return width
    }
    return 0
  }

  const blank = (line: string | undefined) => line === undefined || line.trim() === ""

  // Spec: git's slider rule: a block that could sit anywhere along a run of repeated lines goes after a blank line,
  // ends on one and begins at the shallowest indent; on a tie, the lowest.
  function score(lines: readonly string[], start: number, size: number) {
    let total = 0
    if (blank(lines[start - 1])) total += 10
    if (blank(lines[start + size - 1])) total += 10
    return total - indentOf(lines[start]) - indentOf(lines[start + size])
  }

  function slide(ops: Uint8Array, a: Int32Array, b: Int32Array, oldLines: string[], newLines: string[]) {
    let i = 0
    let j = 0
    let p = 0
    while (p < ops.length) {
      if (ops[p] === CONTEXT) {
        i++
        j++
        p++
        continue
      }
      let q = p
      while (q < ops.length && ops[q] !== CONTEXT) q++
      const kind = ops[p]!
      const size = q - p
      let pure = true
      for (let k = p; k < q; k++) if (ops[k] !== kind) pure = false
      if (!pure) {
        for (let k = p; k < q; k++) {
          if (ops[k] === REMOVED) i++
          else j++
        }
        p = q
        continue
      }
      const ids = kind === ADDED ? b : a
      const text = kind === ADDED ? newLines : oldLines
      const start = kind === ADDED ? j : i
      const context = (at: number) => at >= 0 && at < ops.length && ops[at] === CONTEXT
      let up = 0
      while (
        context(p - up - 1) &&
        (p - up - 2 < 0 || context(p - up - 2)) &&
        ids[start - up - 1] === ids[start + size - up - 1]
      )
        up++
      let down = 0
      while (
        context(q + down) &&
        (q + down + 1 >= ops.length || context(q + down + 1)) &&
        ids[start + down] === ids[start + size + down]
      )
        down++
      let best = 0
      let bestScore = -Infinity
      for (let shift = -up; shift <= down; shift++) {
        const value = score(text, start + shift, size)
        if (value >= bestScore) {
          bestScore = value
          best = shift
        }
      }
      if (best !== 0) {
        ops.fill(CONTEXT, Math.min(p, p + best), Math.max(q, q + best))
        ops.fill(kind, p + best, q + best)
      }
      const after = Math.max(best, 0)
      if (kind === REMOVED) i += size
      else j += size
      i += after
      j += after
      p = q + after
    }
  }

  function splitLines(text: string) {
    if (text === "") return []
    const lines = text.split("\n")
    if (lines.at(-1) === "") lines.pop()
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]!
      if (line.endsWith("\r")) lines[i] = line.slice(0, -1)
    }
    return lines
  }

  function normalize(line: string, mode: IgnoreWhitespace) {
    if (mode === "all") return line.replace(/\s+/g, "")
    if (mode === "change") return line.replace(/\s+/g, " ").trimEnd()
    if (mode === "trailing") return line.trimEnd()
    return line
  }

  function isBinary(text: string) {
    return text.slice(0, BINARY_SNIFF).includes("\0")
  }

  function headingAbove(lines: readonly string[], oldStart: number) {
    for (let index = Math.min(oldStart - 2, lines.length - 1); index >= 0; index--) {
      const line = lines[index]!
      if (/^[A-Za-z_$]/.test(line)) return line.slice(0, 80).trimEnd()
    }
    return undefined
  }

  function empty(status: TextDiff["status"], oldLineCount: number, newLineCount: number): TextDiff {
    return { status, hunks: [], additions: 0, deletions: 0, oldLineCount, newLineCount }
  }

  function diffText(oldText: string, newText: string, options: DiffOptions = {}): TextDiff {
    const maxChars = options.maxChars ?? 20_000_000
    if (oldText.length > maxChars || newText.length > maxChars) return empty("too-large", 0, 0)
    if (isBinary(oldText) || isBinary(newText)) return empty("binary", 0, 0)
    const oldLines = splitLines(oldText)
    const newLines = splitLines(newText)
    const maxLines = options.maxLines ?? 200_000
    if (oldLines.length > maxLines || newLines.length > maxLines) {
      return empty("too-large", oldLines.length, newLines.length)
    }
    const oldOpen = oldText !== "" && !oldText.endsWith("\n")
    const newOpen = newText !== "" && !newText.endsWith("\n")
    const mode = options.ignoreWhitespace ?? "none"
    const ids = new Map<string, number>()
    const intern = (lines: string[], open: boolean) => {
      const out = new Int32Array(lines.length)
      for (let i = 0; i < lines.length; i++) {
        let key = normalize(lines[i]!, mode)
        // Spec: a last line without a newline differs from the same text with one, as git shows it.
        if (open && i === lines.length - 1) key += "\u0000"
        let id = ids.get(key)
        if (id === undefined) {
          id = ids.size
          ids.set(key, id)
        }
        out[i] = id
      }
      return out
    }
    const a = intern(oldLines, oldOpen)
    const b = intern(newLines, newOpen)
    const matches = sequence.match(a, b, options.algorithm, options.maxCost)

    const ops = new Uint8Array(a.length + b.length)
    let count = 0
    for (let i = 0, j = 0; i < a.length || j < b.length;) {
      const match = i < a.length ? matches[i]! : b.length
      if (i < a.length && match === -1) {
        ops[count++] = REMOVED
        i++
      } else if (j < match) {
        ops[count++] = ADDED
        j++
      } else {
        ops[count++] = CONTEXT
        i++
        j++
      }
    }
    slide(ops.subarray(0, count), a, b, oldLines, newLines)

    const lines: DiffLine[] = []
    let additions = 0
    let deletions = 0
    for (let p = 0, i = 0, j = 0; p < count; p++) {
      if (ops[p] === REMOVED) {
        const line: DiffLine = { kind: "removed", text: oldLines[i]!, oldLine: i + 1 }
        if (oldOpen && i === a.length - 1) line.noNewline = true
        lines.push(line)
        deletions++
        i++
      } else if (ops[p] === ADDED) {
        const line: DiffLine = { kind: "added", text: newLines[j]!, newLine: j + 1 }
        if (newOpen && j === b.length - 1) line.noNewline = true
        lines.push(line)
        additions++
        j++
      } else {
        const line: DiffLine = { kind: "context", text: newLines[j]!, oldLine: i + 1, newLine: j + 1 }
        if (newOpen && j === b.length - 1) line.noNewline = true
        lines.push(line)
        i++
        j++
      }
    }

    const context = Math.max(0, options.context ?? 3)
    const hunks: DiffHunk[] = []
    let index = 0
    while (index < lines.length) {
      while (index < lines.length && lines[index]!.kind === "context") index++
      if (index >= lines.length) break
      const start = Math.max(0, index - context)
      let end = index
      for (let scan = index; scan < lines.length; scan++) {
        if (lines[scan]!.kind !== "context") end = scan + 1
        else if (scan - end + 1 > context * 2) break
      }
      const stop = Math.min(lines.length, end + context)
      const slice = lines.slice(start, stop)
      const first = slice[0]!
      let oldCount = 0
      let newCount = 0
      for (const line of slice) {
        if (line.kind !== "added") oldCount++
        if (line.kind !== "removed") newCount++
      }
      const oldStart = first.oldLine ?? firstOld(lines, start)
      const newStart = first.newLine ?? firstNew(lines, start)
      const hunk: DiffHunk = {
        oldStart: oldCount === 0 ? oldStart - 1 : oldStart,
        oldLines: oldCount,
        newStart: newCount === 0 ? newStart - 1 : newStart,
        newLines: newCount,
        lines: slice,
      }
      const heading = headingAbove(oldLines, hunk.oldStart)
      if (heading !== undefined) hunk.heading = heading
      hunks.push(hunk)
      index = stop
    }
    return { status: "ok", hunks, additions, deletions, oldLineCount: a.length, newLineCount: b.length }
  }

  function firstOld(lines: DiffLine[], from: number) {
    for (let k = from; k < lines.length; k++) if (lines[k]!.oldLine !== undefined) return lines[k]!.oldLine!
    for (let k = from - 1; k >= 0; k--) if (lines[k]!.oldLine !== undefined) return lines[k]!.oldLine! + 1
    return 1
  }

  function firstNew(lines: DiffLine[], from: number) {
    for (let k = from; k < lines.length; k++) if (lines[k]!.newLine !== undefined) return lines[k]!.newLine!
    for (let k = from - 1; k >= 0; k--) if (lines[k]!.newLine !== undefined) return lines[k]!.newLine! + 1
    return 1
  }

  return { splitLines, diffText, headingAbove }
}

const lineDiff = createLineDiff(sequenceDiff)
const { diffText, splitLines } = lineDiff

type FilePaths = { oldPath?: string | null; newPath?: string | null }

/** Wraps a computed diff as a file for the views, with both texts so its unchanged regions can expand. */
function toFileDiff(
  diff: TextDiff,
  oldText: string,
  newText: string,
  { oldPath = null, newPath = oldPath }: FilePaths = {},
): FileDiff {
  let status: FileDiff["status"] = "modified"
  if (oldPath === null && newPath !== null) status = "added"
  else if (newPath === null && oldPath !== null) status = "deleted"
  else if (oldPath !== newPath) status = "renamed"
  return {
    oldPath,
    newPath,
    status,
    binary: diff.status === "binary",
    tooLarge: diff.status === "too-large",
    hunks: diff.hunks,
    additions: diff.additions,
    deletions: diff.deletions,
    oldText,
    newText,
  }
}

/** Diffs two versions of a file: `diffText` plus `toFileDiff`. */
function diffFile(oldText: string, newText: string, paths: FilePaths = {}, options?: DiffOptions) {
  return toFileDiff(diffText(oldText, newText, options), oldText, newText, paths)
}

export { createLineDiff, diffFile, diffText, lineDiff, splitLines, toFileDiff }
export type { FilePaths, LineDiff }

import { sequenceDiff } from "@/lib/diff-sequence"
import type { DiffLine, IntralineMode, IntralineRanges } from "@/lib/diff-types"

type Intraline = { old: IntralineRanges; new: IntralineRanges }

type IntralineOptions = {
  mode?: IntralineMode
  /** Lines longer than this get no intraline highlight. @defaultValue 1000 */
  maxLength?: number
  /** Above this share of changed characters on both sides the line counts as rewritten: no highlight. @defaultValue 0.6 */
  maxChangedRatio?: number
}

const wordPattern = /[\p{L}\p{N}_]+|\s+|[^\p{L}\p{N}_\s]/gu

function tokenize(text: string, mode: IntralineMode) {
  if (mode === "char") return Array.from(text)
  return text.match(wordPattern) ?? []
}

function rangesOf(tokens: string[], changed: (index: number) => boolean) {
  const ranges: [number, number][] = []
  let offset = 0
  for (let index = 0; index < tokens.length; index++) {
    const token = tokens[index]!
    const end = offset + token.length
    if (changed(index)) {
      const last = ranges.at(-1)
      if (last && last[1] === offset) last[1] = end
      else ranges.push([offset, end])
    } else if (/^\s$/.test(token) && changed(index - 1) && changed(index + 1)) {
      const last = ranges.at(-1)
      if (last && last[1] === offset) last[1] = end
    }
    offset = end
  }
  return ranges
}

function changedLength(ranges: IntralineRanges) {
  let total = 0
  for (const [start, end] of ranges) total += end - start
  return total
}

/**
 * The words (or characters) that changed between a removed line and the added line paired with it, or `null`
 * when the line was rewritten, is too long, or nothing but whitespace position differs.
 */
function intraline(oldText: string, newText: string, options: IntralineOptions = {}): Intraline | null {
  const { mode = "word", maxLength = 1000, maxChangedRatio = 0.6 } = options
  if (oldText === newText || oldText.length > maxLength || newText.length > maxLength) return null
  const oldTokens = tokenize(oldText, mode)
  const newTokens = tokenize(newText, mode)
  const ids = new Map<string, number>()
  const intern = (tokens: string[]) =>
    Int32Array.from(tokens, (token) => {
      let id = ids.get(token)
      if (id === undefined) {
        id = ids.size
        ids.set(token, id)
      }
      return id
    })
  const a = intern(oldTokens)
  const b = intern(newTokens)
  const matches = sequenceDiff.match(a, b, "myers")
  const matchedB = new Uint8Array(b.length)
  for (const j of matches) if (j >= 0) matchedB[j] = 1
  const old = rangesOf(oldTokens, (index) => index >= 0 && index < a.length && matches[index] === -1)
  const next = rangesOf(newTokens, (index) => index >= 0 && index < b.length && matchedB[index] === 0)
  if (old.length === 0 && next.length === 0) return null
  const oldRatio = oldText.length === 0 ? 1 : changedLength(old) / oldText.length
  const newRatio = newText.length === 0 ? 1 : changedLength(next) / newText.length
  if (oldRatio > maxChangedRatio && newRatio > maxChangedRatio) return null
  return { old, new: next }
}

/**
 * Pairs the removed and added lines of each change block in order, the way unified and split views line them
 * up: the first removed line with the first added one, and so on. Returns each line's partner.
 */
function pairLines(lines: readonly DiffLine[]) {
  const partners = new Map<DiffLine, DiffLine>()
  let index = 0
  while (index < lines.length) {
    if (lines[index]!.kind === "context") {
      index++
      continue
    }
    const removed: DiffLine[] = []
    const added: DiffLine[] = []
    while (index < lines.length && lines[index]!.kind === "removed") removed.push(lines[index++]!)
    while (index < lines.length && lines[index]!.kind === "added") added.push(lines[index++]!)
    for (let k = 0; k < Math.min(removed.length, added.length); k++) {
      partners.set(removed[k]!, added[k]!)
      partners.set(added[k]!, removed[k]!)
    }
  }
  return partners
}

export { intraline, pairLines }
export type { Intraline, IntralineOptions }

import type { DiffHunk, DiffLine, FileDiff } from "@/lib/diff-types"

const hunkHeader = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@ ?(.*)$/

// Spec: git quotes a path with unusual bytes as a C string: "a/caf\303\251.txt".
function unquote(path: string) {
  if (!path.startsWith('"')) return path
  const bytes: number[] = []
  const escapes: Record<string, number> = { n: 10, t: 9, r: 13, b: 8, f: 12, a: 7, v: 11, '"': 34, "\\": 92 }
  const encoder = new TextEncoder()
  for (let index = 1; index < path.length - 1; index++) {
    const char = path[index]!
    if (char !== "\\") {
      bytes.push(...encoder.encode(char))
      continue
    }
    const next = path[index + 1] ?? ""
    if (/[0-7]/.test(next)) {
      const octal = path.slice(index + 1, index + 4).match(/^[0-7]{1,3}/)![0]
      bytes.push(Number.parseInt(octal, 8))
      index += octal.length
    } else {
      bytes.push(escapes[next] ?? next.charCodeAt(0))
      index++
    }
  }
  return new TextDecoder().decode(new Uint8Array(bytes))
}

function stripPrefix(path: string, prefixed: boolean) {
  if (!prefixed) return path
  return path.replace(/^[a-z]\//, "")
}

// Spec: `--- a/path\t2024-01-01 …`: a timestamp may follow a tab.
function headerPath(rest: string) {
  const value = rest.startsWith('"') ? rest.slice(0, rest.indexOf('"', 1) + 1) : rest.split("\t")[0]!.trimEnd()
  return value === "/dev/null" ? null : unquote(value)
}

// Spec: `diff --git a/x b/x`: with spaces in the name the two halves are equal.
function gitHeaderPaths(rest: string): [string, string] | null {
  if (rest.startsWith('"')) {
    const end = rest.indexOf('"', 1)
    const first = rest.slice(0, end + 1)
    return [unquote(first), unquote(rest.slice(end + 2))]
  }
  const quoted = rest.indexOf(' "')
  if (quoted > 0) return [rest.slice(0, quoted), unquote(rest.slice(quoted + 1))]
  const middle = (rest.length - 1) / 2
  if (Number.isInteger(middle) && rest[middle] === " ") return [rest.slice(0, middle), rest.slice(middle + 1)]
  const parts = rest.split(" ")
  return parts.length === 2 ? [parts[0]!, parts[1]!] : null
}

function newFile(): FileDiff {
  return {
    oldPath: null,
    newPath: null,
    status: "modified",
    binary: false,
    hunks: [],
    additions: 0,
    deletions: 0,
  }
}

function finish(file: FileDiff, prefixed: boolean, fallback: [string, string] | null) {
  if (fallback) {
    const [oldPath, newPath] = fallback.map((path) => stripPrefix(path, prefixed))
    if (file.oldPath === null && file.status !== "added") file.oldPath = oldPath ?? null
    if (file.newPath === null && file.status !== "deleted") file.newPath = newPath ?? null
  }
  if (file.status === "modified" && file.oldPath && file.newPath && file.oldPath !== file.newPath) {
    file.status = "renamed"
  }
  if (file.status === "added") file.oldPath = null
  if (file.status === "deleted") file.newPath = null
  return file
}

/**
 * Parses a unified diff, as `git diff`, `git show` or `git format-patch` print it, or a plain `diff -u`: every file
 * with its paths, status (added, deleted, modified, renamed, copied), modes, similarity, binary flag and hunks.
 * Anything before the first file (a commit message, mail headers) is skipped.
 */
function parsePatch(patch: string): FileDiff[] {
  const lines = patch.split("\n")
  const files: FileDiff[] = []
  let file: FileDiff | null = null
  let prefixed = true
  let gitPaths: [string, string] | null = null
  let index = 0

  const close = () => {
    if (file) files.push(finish(file, prefixed, gitPaths))
    file = null
    gitPaths = null
  }

  while (index < lines.length) {
    let line = lines[index]!
    if (line.endsWith("\r")) line = line.slice(0, -1)
    if (line.startsWith("diff --git ")) {
      close()
      file = newFile()
      gitPaths = gitHeaderPaths(line.slice("diff --git ".length))
      prefixed = gitPaths !== null && /^[a-z]\//.test(gitPaths[0]) && /^[a-z]\//.test(gitPaths[1])
      index++
      continue
    }
    if (line.startsWith("diff --cc ") || line.startsWith("diff --combined ")) {
      close()
      index++
      continue
    }
    if (line.startsWith("--- ") && lines[index + 1]?.startsWith("+++ ")) {
      const current: FileDiff = file ?? newFile()
      if (!file) {
        close()
        file = current
        prefixed = /^"?[a-z]\//.test(line.slice(4)) && /^"?[a-z]\//.test(lines[index + 1]!.slice(4))
      }
      const oldPath = headerPath(line.slice(4).replace(/\r$/, ""))
      const newPath = headerPath(lines[index + 1]!.slice(4).replace(/\r$/, ""))
      current.oldPath = oldPath === null ? null : stripPrefix(oldPath, prefixed)
      current.newPath = newPath === null ? null : stripPrefix(newPath, prefixed)
      if (oldPath === null) current.status = "added"
      if (newPath === null) current.status = "deleted"
      index += 2
      continue
    }
    const header = hunkHeader.exec(line)
    if (header && file) {
      index = readHunk(lines, index, header, file)
      continue
    }
    if (file) readExtended(line, file)
    index++
  }
  close()
  return files
}

function readExtended(line: string, file: FileDiff) {
  const value = (prefix: string) => line.slice(prefix.length)
  if (line.startsWith("new file mode ")) {
    file.status = "added"
    file.newMode = value("new file mode ")
  } else if (line.startsWith("deleted file mode ")) {
    file.status = "deleted"
    file.oldMode = value("deleted file mode ")
  } else if (line.startsWith("old mode ")) file.oldMode = value("old mode ")
  else if (line.startsWith("new mode ")) file.newMode = value("new mode ")
  else if (line.startsWith("rename from ")) {
    file.status = "renamed"
    file.oldPath = unquote(value("rename from "))
  } else if (line.startsWith("rename to ")) file.newPath = unquote(value("rename to "))
  else if (line.startsWith("copy from ")) {
    file.status = "copied"
    file.oldPath = unquote(value("copy from "))
  } else if (line.startsWith("copy to ")) file.newPath = unquote(value("copy to "))
  else if (line.startsWith("similarity index ")) file.similarity = Number.parseInt(value("similarity index "), 10)
  else if (line.startsWith("Binary files ") || line === "GIT binary patch") file.binary = true
  else if (line.startsWith("index ")) {
    const mode = /^index \S+ (\d+)$/.exec(line)?.[1]
    if (mode) {
      file.oldMode ??= mode
      file.newMode ??= mode
    }
  }
}

function readHunk(lines: string[], start: number, header: RegExpExecArray, file: FileDiff) {
  const hunk: DiffHunk = {
    oldStart: Number(header[1]),
    oldLines: header[2] === undefined ? 1 : Number(header[2]),
    newStart: Number(header[3]),
    newLines: header[4] === undefined ? 1 : Number(header[4]),
    lines: [],
  }
  if (header[5]) hunk.heading = header[5]
  let oldLine = hunk.oldStart
  let newLine = hunk.newStart
  let oldLeft = hunk.oldLines
  let newLeft = hunk.newLines
  let index = start + 1
  let last: DiffLine | undefined
  // Spec: the counts, not the markers, say where a hunk ends: a removed line can begin with "--".
  while (index < lines.length && (oldLeft > 0 || newLeft > 0 || lines[index]!.startsWith("\\"))) {
    let raw = lines[index]!
    if (raw.endsWith("\r")) raw = raw.slice(0, -1)
    const marker = raw[0]
    const text = raw.slice(1)
    if (marker === "\\") {
      if (last) last.noNewline = true
      index++
      continue
    }
    if (oldLeft <= 0 && newLeft <= 0) break
    if (marker === "+") {
      last = { kind: "added", text, newLine: newLine++ }
      newLeft--
      file.additions++
    } else if (marker === "-") {
      last = { kind: "removed", text, oldLine: oldLine++ }
      oldLeft--
      file.deletions++
    } else if (marker === " " || raw === "") {
      last = { kind: "context", text, oldLine: oldLine++, newLine: newLine++ }
      oldLeft--
      newLeft--
    } else break
    hunk.lines.push(last)
    index++
  }
  file.hunks.push(hunk)
  return index
}

function range(start: number, count: number) {
  return count === 1 ? String(start) : `${String(start)},${String(count)}`
}

/** Writes hunks back as unified-diff text, `@@` headers included, the way git prints them. */
function formatHunks(hunks: readonly DiffHunk[]) {
  const out: string[] = []
  for (const hunk of hunks) {
    const heading = hunk.heading ? ` ${hunk.heading}` : ""
    out.push(`@@ -${range(hunk.oldStart, hunk.oldLines)} +${range(hunk.newStart, hunk.newLines)} @@${heading}`)
    for (const line of hunk.lines) {
      out.push((line.kind === "added" ? "+" : line.kind === "removed" ? "-" : " ") + line.text)
      if (line.noNewline) out.push("\\ No newline at end of file")
    }
  }
  return out.join("\n")
}

export { formatHunks, parsePatch }

import { createLineDiff, diffText } from "@/lib/diff-lines"
import { createSequenceDiff } from "@/lib/diff-sequence"
import type { DiffOptions, TextDiff } from "@/lib/diff-types"

type AsyncDiffOptions = DiffOptions & {
  signal?: AbortSignal
  /**
   * `"auto"` (default) diffs in a Web Worker when the two texts together pass `workerThreshold` characters,
   * `true` always does where workers exist, `false` never does.
   */
  worker?: boolean | "auto"
  /** @defaultValue 200000 */
  workerThreshold?: number
}

type Pending = { resolve: (diff: TextDiff) => void; reject: (error: unknown) => void }

const WORKER_THRESHOLD = 200_000

let worker: Worker | null = null
let broken = false
let nextId = 0
const pending = new Map<number, Pending>()

// Workaround: shadcn copies registry files into a consumer's folders, where `new URL("./x.worker.ts",
// import.meta.url)` resolves only under bundlers that compile it, so the worker is built from the engine's source
// in a Blob. `__name` covers esbuild's keepNames helper.
function workerSource() {
  return [
    '"use strict";',
    "var __name = function (target) { return target };",
    `var sequence = (${String(createSequenceDiff)})();`,
    `var lines = (${String(createLineDiff)})(sequence);`,
    "self.onmessage = function (event) {",
    "  var data = event.data;",
    "  try { self.postMessage({ id: data.id, result: lines.diffText(data.oldText, data.newText, data.options) }) }",
    "  catch (error) { self.postMessage({ id: data.id, error: String((error && error.message) || error) }) }",
    "};",
  ].join("\n")
}

function failAll(error: unknown) {
  for (const entry of pending.values()) entry.reject(error)
  pending.clear()
}

function stopWorker() {
  worker?.terminate()
  worker = null
}

function getWorker() {
  if (worker || broken) return worker
  if (typeof Worker === "undefined" || typeof Blob === "undefined" || typeof URL.createObjectURL !== "function") {
    broken = true
    return null
  }
  try {
    const url = URL.createObjectURL(new Blob([workerSource()], { type: "text/javascript" }))
    worker = new Worker(url)
    URL.revokeObjectURL(url)
  } catch {
    // Security: a Content Security Policy without `worker-src blob:` refuses it.
    broken = true
    return null
  }
  worker.addEventListener("message", (event: MessageEvent<{ id: number; result?: TextDiff; error?: string }>) => {
    const entry = pending.get(event.data.id)
    if (!entry) return
    pending.delete(event.data.id)
    if (event.data.result) entry.resolve(event.data.result)
    else entry.reject(new Error(event.data.error ?? "Diff failed"))
  })
  worker.addEventListener("error", (event) => {
    event.preventDefault()
    broken = true
    stopWorker()
    failAll(new Error("The diff worker failed to start"))
  })
  return worker
}

function abortError() {
  return new DOMException("The diff was aborted", "AbortError")
}

function shouldUseWorker(oldText: string, newText: string, options: AsyncDiffOptions) {
  const { worker: mode = "auto", workerThreshold = WORKER_THRESHOLD } = options
  if (mode === false) return false
  return mode === true || oldText.length + newText.length > workerThreshold
}

function viaWorker(target: Worker, oldText: string, newText: string, options: AsyncDiffOptions) {
  const { signal, worker: _mode, workerThreshold: _threshold, ...diffOptions } = options
  const id = nextId++
  return new Promise<TextDiff>((resolve, reject) => {
    const onAbort = () => {
      if (!pending.delete(id)) return
      // Spec: a worker can't stop mid-diff.
      stopWorker()
      failAll(abortError())
      reject(abortError())
    }
    pending.set(id, {
      resolve: (diff) => {
        signal?.removeEventListener("abort", onAbort)
        resolve(diff)
      },
      reject: (error) => {
        signal?.removeEventListener("abort", onAbort)
        reject(error)
      },
    })
    signal?.addEventListener("abort", onAbort, { once: true })
    // oxlint-disable-next-line unicorn/require-post-message-target-origin -- Worker.postMessage takes no origin
    target.postMessage({ id, oldText, newText, options: diffOptions })
  })
}

/**
 * `diffText` that runs in a Web Worker past `workerThreshold` characters, so a 20,000-line file doesn't block
 * typing or scrolling, and on the main thread below it, without workers (server, tests) or when a Content
 * Security Policy blocks a `blob:` worker. Rejects with an `AbortError` when `signal` aborts.
 */
async function diffTextAsync(oldText: string, newText: string, options: AsyncDiffOptions = {}): Promise<TextDiff> {
  if (options.signal?.aborted) throw abortError()
  const target = shouldUseWorker(oldText, newText, options) ? getWorker() : null
  if (target) {
    try {
      return await viaWorker(target, oldText, newText, options)
    } catch (error) {
      if (error instanceof DOMException && error.name === "AbortError") throw error
      if (!broken) throw error
    }
  }
  const { signal: _signal, worker: _mode, workerThreshold: _threshold, ...diffOptions } = options
  return diffText(oldText, newText, diffOptions)
}

/** Whether `diffTextAsync` would use a worker for these texts, for a caller that diffs small inputs during render. */
function diffsInWorker(oldText: string, newText: string, options: AsyncDiffOptions = {}) {
  return shouldUseWorker(oldText, newText, options) && !broken && typeof Worker !== "undefined"
}

export { diffsInWorker, diffTextAsync, WORKER_THRESHOLD }
export type { AsyncDiffOptions }
